//! Worldgen P27 dependency-composition plan contract.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};use bioprism_ids::ContentHash;use serde::{Deserialize,Serialize};use serde_json::json;use std::collections::{BTreeSet,BTreeMap};use thiserror::Error;
pub const FEATURE_ID:&str="AFA-worldgen-P27-F01";pub const CONTRACT_VERSION:&str="worldgen-local-dependency-composition/1.0";pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.dependency-composition-receipt-1+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct DependencyNode4{pub node_id:String,pub capability_id:String,pub version:String,pub consumer:String,pub input_digest:ContentHash,pub output_digest:ContentHash,pub evidence_state:String,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct DependencyEdge4{pub from:String,pub to:String,pub required:bool,pub semantic_loss:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct DependencyCompositionRequest4{pub request_id:String,pub scope:String,pub nodes:Vec<DependencyNode4>,pub edges:Vec<DependencyEdge4>,pub required_root_order:Vec<String>,pub max_depth:u32,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub network_available:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:ContentHash,pub adversarial_events:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct DependencyCompositionArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub node_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct DependencyCompositionCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub disposition:String,pub node_order:Vec<String>,pub edge_order:Vec<String>,pub root_order:Vec<String>,pub resolved_order:Vec<String>,pub blocked_order:Vec<String>,pub omitted_order:Vec<String>,pub cycle_order:Vec<String>,pub uncertainty_order:Vec<String>,pub semantic_loss_order:Vec<String>,pub replay_identity:ContentHash,pub composition_digest:ContentHash,pub artifact:DependencyCompositionArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum DependencyCompositionError{#[error("invalid dependency-composition request: {0}")]Invalid(String),#[error("dependency-composition card failed validation: {0}")]Output(String)}
fn ord(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn dig(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn ne(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":id,"version":version,"owner_crate":"worldgen","consumers":["workflow compiler","dependency steward","research operator","release auditor"],"behavior":format!("compose typed capability dependencies with cycle and semantic-loss receipts at {scale} ({mode})"),"value":"prevents undeclared, cyclic, or semantically lossy capability plans from executing","input_schema":"DependencyCompositionRequest4@1","output_schema":"DependencyCompositionCard7@1","effects":["emit:composition-plan","block:unsafe-release"],"permissions":["read:local-capability-graph"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
impl DependencyCompositionCard7{pub fn validate(&self)->Result<(),DependencyCompositionError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||!ne(&self.contract_version)||!ne(&self.feature_id)||!ne(&self.mode)||!ne(&self.scale)||!ne(&self.request_id)||self.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.node_order.is_empty()||!ord(&self.node_order)||!ord(&self.edge_order)||!ord(&self.root_order)||!ord(&self.resolved_order)||!ord(&self.blocked_order)||!ord(&self.omitted_order)||!ord(&self.cycle_order)||!ord(&self.uncertainty_order)||!ord(&self.semantic_loss_order)||!dig(&self.replay_identity)||!dig(&self.composition_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.composition_digest||self.artifact.boundary!=PRECLINICAL_BOUNDARY{return Err(DependencyCompositionError::Output("composition identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.node_order.iter().cloned());let parts=self.resolved_order.iter().chain(&self.blocked_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.node_order.len()||parts.len()!=ids.len()||BTreeSet::from_iter(parts)!=ids{return Err(DependencyCompositionError::Output("dependency states do not partition".into()))}Ok(())}}
pub fn compose(request:&DependencyCompositionRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<DependencyCompositionCard7,DependencyCompositionError>{if !ne(&request.request_id)||!ne(&request.scope)||request.nodes.is_empty()||request.required_root_order.is_empty()||request.max_depth==0||!dig(&request.replay_identity)||request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ord(&request.required_root_order)||!ord(&request.adversarial_events){return Err(DependencyCompositionError::Invalid("composition identity, roots, depth, digest, ordering, locality, or boundary is invalid".into()))}let mut nodes=request.nodes.clone();nodes.sort_by(|a,b|a.node_id.cmp(&b.node_id));let mut ids=BTreeSet::new();let mut node_order=Vec::new();let mut digests=BTreeSet::new();for n in &nodes{if !ids.insert(n.node_id.clone())||!ne(&n.node_id)||!ne(&n.capability_id)||!ne(&n.version)||!ne(&n.consumer)||!dig(&n.input_digest)||!dig(&n.output_digest)||!n.local||!n.aggregate_only{return Err(DependencyCompositionError::Invalid("node identity, consumer, digest, or locality is invalid".into()))}node_order.push(n.node_id.clone());digests.insert(n.output_digest.clone());}let mut edges=request.edges.clone();edges.sort_by(|a,b|format!("{}>{}",a.from,a.to).cmp(&format!("{}>{}",b.from,b.to)));let mut edge_order=Vec::new();let mut adjacency:BTreeMap<String,BTreeSet<String>>=BTreeMap::new();let mut indegree:BTreeMap<String,usize>=ids.iter().map(|id|(id.clone(),0)).collect();let mut loss=BTreeSet::new();for e in &edges{if !ids.contains(&e.from)||!ids.contains(&e.to)||e.from==e.to{return Err(DependencyCompositionError::Invalid("edge endpoint or self-cycle is invalid".into()))}edge_order.push(format!("{}>{}",e.from,e.to));adjacency.entry(e.from.clone()).or_default().insert(e.to.clone());*indegree.entry(e.to.clone()).or_default()+=1;if e.required&&!ne(&e.semantic_loss){loss.insert(format!("{}>{}:semantic-loss-undeclared",e.from,e.to));}else if ne(&e.semantic_loss){loss.insert(format!("{}>{}:{}",e.from,e.to,e.semantic_loss));}}let mut ready=indegree.iter().filter(|(_,v)|**v==0).map(|(k,_)|k.clone()).collect::<BTreeSet<_>>();let mut topo=Vec::new();while let Some(n)=ready.pop_first(){topo.push(n.clone());if let Some(next)=adjacency.get(&n){for child in next{let d=indegree.get_mut(child).unwrap();*d-=1;if *d==0{ready.insert(child.clone());}}}}let cycle=node_order.iter().filter(|n|!topo.contains(n)).cloned().collect::<Vec<_>>();let mut resolved=BTreeSet::from_iter(topo.iter().cloned());let mut blocked=BTreeSet::from_iter(cycle.iter().cloned());let mut omitted=BTreeSet::new();let mut uncertainty:BTreeSet<String>=BTreeSet::new();if !cycle.is_empty(){uncertainty.insert("graph:cycle-detected".into());}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.network_available||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty();if global{omitted.extend(node_order.iter().cloned());resolved.clear();blocked.clear();}let roots=BTreeSet::from_iter(request.required_root_order.iter().cloned());let root_ok=roots.is_subset(&resolved);let disposition=if global{"blocked"}else if !cycle.is_empty(){"blocked"}else if root_ok&&loss.is_empty(){"composed"}else{"unresolved"};if disposition!="composed"{uncertainty.insert("composition:release-gate-incomplete".into());}let mut payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"disposition":disposition,"node_order":node_order,"edge_order":edge_order,"root_order":request.required_root_order,"resolved_order":resolved.into_iter().collect::<Vec<_>>(),"blocked_order":blocked.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"cycle_order":cycle,"uncertainty_order":uncertainty.into_iter().collect::<Vec<_>>(),"semantic_loss_order":loss.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let digest=ContentHash::of_value(&payload).map_err(|e|DependencyCompositionError::Output(e.to_string()))?;payload["composition_digest"]=json!(digest);payload["artifact"]=json!({"artifact_id":format!("worldgen-dependency-composition:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":digest,"semantic_loss":payload["semantic_loss_order"],"node_digests":digests.into_iter().collect::<Vec<_>>(),"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=json!(if disposition=="composed"{vec![format!("emit:composition-plan:{}",request.request_id)]}else{vec!["block:unsafe-release".to_string()]});let out:DependencyCompositionCard7=serde_json::from_value(payload).map_err(|e|DependencyCompositionError::Output(e.to_string()))?;out.validate()?;Ok(out)}
